    54→private struct CallView: UIViewRepresentable {
    55→    /// The top-level view this representable displays. It wraps the web view when picture in picture isn't running.
    56→    typealias WebViewWrapper = UIView
    57→    
    58→    let url: URL?
    59→    let viewModelContext: CallScreenViewModel.Context
    60→    
    61→    func makeUIView(context: Context) -> WebViewWrapper {
    62→        context.coordinator.webViewWrapper
    63→    }
    64→    
    65→    func makeCoordinator() -> Coordinator {
    66→        Coordinator(viewModelContext: viewModelContext)
    67→    }
    68→    
    69→    func updateUIView(_ callWebView: WebViewWrapper, context: Context) {
    70→        if let url {
    71→            context.coordinator.load(url)
    72→        }
    73→    }
    74→    
    75→    @MainActor
    76→    class Coordinator: NSObject, WKUIDelegate, WKNavigationDelegate, AVPictureInPictureControllerDelegate {
    77→        private weak var viewModelContext: CallScreenViewModel.Context?
    78→        private let certificateValidator: CertificateValidatorHookProtocol
    79→        
    80→        private var webView: WKWebView!
    81→        private var pictureInPictureController: AVPictureInPictureController?
    82→        private let pictureInPictureViewController: AVPictureInPictureVideoCallViewController
    83→        private var routePickerView: AVRoutePickerView!
    84→        
    85→        /// The view to be shown in the app. This will contain the web view when picture in picture isn't running.
    86→        let webViewWrapper = WebViewWrapper(frame: .zero)
    87→        
    88→        private var url: URL!
    89→        
    90→        init(viewModelContext: CallScreenViewModel.Context) {
    91→            self.viewModelContext = viewModelContext
    92→            certificateValidator = viewModelContext.viewState.certificateValidator
    93→            pictureInPictureViewController = AVPictureInPictureVideoCallViewController()
    94→            pictureInPictureViewController.preferredContentSize = CGSize(width: 1920, height: 1080)
    95→            
    96→            super.init()
    97→            
    98→            DispatchQueue.main.async { // Avoid `Publishing changes from within view update` warnings
    99→                viewModelContext.javaScriptEvaluator = self.evaluateJavaScript
   100→                viewModelContext.requestPictureInPictureHandler = self.requestPictureInPicture
   101→            }
   102→            
   103→            let configuration = WKWebViewConfiguration()
   104→            
   105→            let userContentController = WKUserContentController()
   106→            CallScreenJavaScriptMessageName.allCases.forEach {
   107→                userContentController.add(WKScriptMessageHandlerWrapper(self), name: $0.rawValue)
   108→            }
   109→            
   110→            // Required to allow a webview that uses file URL to load its own assets
   111→            configuration.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
   112→            configuration.userContentController = userContentController
   113→            configuration.allowsInlineMediaPlayback = true
   114→            configuration.allowsPictureInPictureMediaPlayback = true
   115→            
   116→            if let script = viewModelContext.viewState.script {
   117→                let userScript = WKUserScript(source: script, injectionTime: .atDocumentEnd, forMainFrameOnly: false)
   118→                configuration.userContentController.addUserScript(userScript)
   119→            }
   120→            
   121→            webView = WKWebView(frame: .zero, configuration: configuration)
   122→            webView.uiDelegate = self
   123→            webView.navigationDelegate = self
   124→            webView.isInspectable = true
   125→            
   126→            webView.customUserAgent = UserAgentBuilder.makeASCIIUserAgent()
   127→            
   128→            // https://stackoverflow.com/a/77963877/730924
   129→            webView.allowsLinkPreview = true
   130→            
   131→            // Try matching Element Call colors
   132→            webView.isOpaque = false
   133→            webView.backgroundColor = .compound.bgCanvasDefault
   134→            webView.scrollView.backgroundColor = .compound.bgCanvasDefault
   135→            
   136→            // This button is always hidden and is only used to be programmaticaly tapped
   137→            routePickerView = AVRoutePickerView(frame: .zero)
   138→            routePickerView.isHidden = true
   139→            routePickerView.isUserInteractionEnabled = false
   140→            webView.addSubview(routePickerView)
   141→            
   142→            webViewWrapper.addMatchedSubview(webView)
   143→            
   144→            if AVPictureInPictureController.isPictureInPictureSupported() {
   145→                let pictureInPictureController = AVPictureInPictureController(contentSource: .init(activeVideoCallSourceView: webViewWrapper,
   146→                                                                                                   contentViewController: pictureInPictureViewController))
   147→                pictureInPictureController.delegate = self
   148→                self.pictureInPictureController = pictureInPictureController
   149→                viewModelContext.send(viewAction: .pictureInPictureIsAvailable(pictureInPictureController))
   150→            }
   151→        }
   152→        
   153→        func load(_ url: URL) {
   154→            self.url = url
   155→            // The only file URL we allow is the one coming from our own local ElementCall bundle, so it's okay to allow read permission only to our local EC bundle
   156→            if url.isFileURL {
   157→                webView.loadFileURL(url, allowingReadAccessTo: EmbeddedElementCall.bundle.bundleURL)
   158→            } else {
   159→                let request = URLRequest(url: url)
   160→                webView.load(request)
   161→            }
   162→        }
   163→        
   164→        func evaluateJavaScript(_ script: String) async throws -> Any? {
   165→            // After testing different scenarios it seems that when using async/await version of these
   166→            // methods wkwebView expects JavaScript to return with a value (something other than Void),
   167→            // if there is no value returning from the JavaScript that you evaluate you will have a crash.
   168→            try await withCheckedThrowingContinuation { [weak self] continuaton in
   169→                self?.webView.evaluateJavaScript(script) { result, error in
   170→                    if let error {
   171→                        continuaton.resume(throwing: error)
   172→                    } else {
   173→                        continuaton.resume(returning: result)
   174→                    }
   175→                }
   176→            }
   177→        }
   178→        
   179→        func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
   180→            guard let handlerID = CallScreenJavaScriptMessageName(rawValue: message.name) else {
   181→                return
   182→            }
   183→            
   184→            switch handlerID {
   185→            case .widgetAction:
   186→                guard let message = message.body as? String else { return }
   187→                viewModelContext?.send(viewAction: .widgetAction(message: message))
   188→            case .showNativeOutputDevicePicker:
   189→                DispatchQueue.main.async {
   190→                    self.tapRoutePickerView()
   191→                }
   192→            case .onOutputDeviceSelect:
   193→                guard let deviceID = message.body as? String else { return }
   194→                viewModelContext?.send(viewAction: .outputDeviceSelected(deviceID: deviceID))
   195→            case .onBackButtonPressed:
   196→                viewModelContext?.send(viewAction: .navigateBack)
   197→            }
   198→        }
   199→        
   200→        /// This function is called by the webview output routing button
   201→        /// it allows to open the OS output selector using the hidden button.
   202→        private func tapRoutePickerView() {
   203→            guard let button = routePickerView.subviews.first(where: { $0 is UIButton }) as? UIButton else {
   204→                return
   205→            }
   206→            
   207→            button.sendActions(for: .touchUpInside)
   208→        }
   209→        
   210→        // MARK: - WKUIDelegate
   211→        
   212→        func webView(_ webView: WKWebView, decideMediaCapturePermissionsFor origin: WKSecurityOrigin, initiatedBy frame: WKFrameInfo, type: WKMediaCaptureType) async -> WKPermissionDecision {
   213→            // Allow if the origin is local, otherwise don't allow permissions for domains different than what the call was started on
   214→            guard origin.protocol == "file" || origin.host == url.host else {
   215→                return .deny
   216→            }
   217→            
   218→            viewModelContext?.send(viewAction: .mediaCapturePermissionGranted)
   219→            return .grant
   220→        }
   221→        
   222→        // MARK: - WKNavigationDelegate
   223→        
   224→        func webView(_ webView: WKWebView, respondTo challenge: URLAuthenticationChallenge) async -> (URLSession.AuthChallengeDisposition, URLCredential?) {
   225→            await certificateValidator.respondTo(challenge)
   226→        }
   227→        
   228→        func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction) async -> WKNavigationActionPolicy {
   229→            if let navigationURL = navigationAction.request.url {
   230→                // Do not allow navigation to a different URL scheme.
   231→                if navigationURL.scheme != url.scheme {
   232→                    return .cancel
   233→                }
   234→                
   235→                // Allow any content from the main URL.
   236→                if navigationURL.host == url.host {
   237→                    return .allow
   238→                }
   239→            }
   240→            
   241→            // Additionally allow any embedded content such as captchas.
   242→            if let targetFrame = navigationAction.targetFrame, !targetFrame.isMainFrame {
   243→                return .allow
   244→            }
   245→            
   246→            // Otherwise the request is invalid.
   247→            return .cancel
   248→        }
   249→        
   250→        func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
   251→            viewModelContext?.send(viewAction: .urlChanged(webView.url))
   252→        }
   253→        
   254→        // MARK: - Picture in Picture
   255→        
   256→        func requestPictureInPicture() async -> Result<Void, CallScreenError> {
   257→            guard let pictureInPictureController,
   258→                  pictureInPictureController.isPictureInPicturePossible,
   259→                  case .success(true) = await webViewCanEnterPictureInPicture() else {
   260→                return .failure(.pictureInPictureNotAvailable)
   261→            }
   262→            
   263→            pictureInPictureController.startPictureInPicture()
   264→            return .success(())
   265→        }
   266→        
   267→        func stopPictureInPicture() {
   268→            pictureInPictureController?.stopPictureInPicture()
   269→        }
   270→        
   271→        nonisolated func pictureInPictureControllerWillStartPictureInPicture(_ pictureInPictureController: AVPictureInPictureController) {
   272→            Task { @MainActor in
   273→                // We move the view via the delegate so it works when you background the app without calling requestPictureInPicture
   274→                pictureInPictureViewController.view.addMatchedSubview(webView)
   275→                _ = try? await evaluateJavaScript("controls.enablePip()")
   276→            }
   277→        }
   278→        
   279→        nonisolated func pictureInPictureControllerDidStartPictureInPicture(_ pictureInPictureController: AVPictureInPictureController) {
   280→            Task { @MainActor in
   281→                // Double check that the controller is definitely showing a page that supports picture in picture.
   282→                // This is necessary as it doesn't get checked when backgrounding the app or tapping a notification.
   283→                guard case .success(true) = await webViewCanEnterPictureInPicture() else {
   284→                    MXLog.error("Picture in picture started on a webpage that doesn't support it. Ending the call.")
   285→                    viewModelContext?.send(viewAction: .endCall)
   286→                    return
   287→                }
   288→            }
   289→        }
   290→        
   291→        nonisolated func pictureInPictureControllerWillStopPictureInPicture(_ pictureInPictureController: AVPictureInPictureController) {
   292→            Task { await viewModelContext?.send(viewAction: .pictureInPictureWillStop) }
   293→        }
   294→        
   295→        nonisolated func pictureInPictureControllerDidStopPictureInPicture(_ pictureInPictureController: AVPictureInPictureController) {
   296→            Task { @MainActor in
   297→                webViewWrapper.addMatchedSubview(webView)
   298→                _ = try? await evaluateJavaScript("controls.disablePip()")
   299→            }
   300→        }
   301→        
   302→        /// Whether the web view can do picture in picture or not (e.g. it is showing an error or the page didn't load).
   303→        private func webViewCanEnterPictureInPicture() async -> Result<Bool, CallScreenError> {
   304→            do {
   305→                guard let canEnterPictureInPicture = try await evaluateJavaScript("controls.canEnterPip()") as? Bool else {
   306→                    MXLog.error("canEnterPip returned an unexpected value, skipping picture in picture.")
   307→                    return .failure(.pictureInPictureNotAvailable)
   308→                }
   309→                MXLog.info("canEnterPip returned \(canEnterPictureInPicture)")
   310→                return .success(canEnterPictureInPicture)
   311→            } catch {
   312→                MXLog.error("Error checking canEnterPip: \(error)")
   313→                return .failure(.pictureInPictureNotAvailable)
   314→            }
   315→        }
   316→    }
