   318→    /// Avoids retain loops between the configuration and webView coordinator
   319→    private class WKScriptMessageHandlerWrapper: NSObject, WKScriptMessageHandler {
   320→        private weak var coordinator: Coordinator?
   321→        
   322→        init(_ coordinator: Coordinator) {
   323→            self.coordinator = coordinator
