    19→struct CallScreenViewState: BindableState {
    20→    let script: String?
    21→    var url: URL?
    22→    let isGenericCallLink: Bool
    23→    
    24→    let certificateValidator: CertificateValidatorHookProtocol
    25→    
    26→    var bindings = Bindings()
    27→}
