    29→struct Bindings {
    30→    var javaScriptEvaluator: ((String) async throws -> Any)?
    31→    var requestPictureInPictureHandler: (() async -> Result<Void, CallScreenError>)?
    32→    
    33→    var alertInfo: AlertInfo<UUID>?
    34→}
    35→
    36→enum CallScreenViewAction {
    37→    case urlChanged(URL?)
    38→    case pictureInPictureIsAvailable(AVPictureInPictureController)
    39→    case navigateBack
    40→    case pictureInPictureWillStop
    41→    case endCall
    42→    case mediaCapturePermissionGranted
    43→    case outputDeviceSelected(deviceID: String)
    44→    case widgetAction(message: String)
    45→}
