   108→struct DecodedWidgetMessage: Decodable {
   109→    private static let decoder = JSONDecoder()
   110→    private static let contentLoadedAction = "content_loaded"
   111→    private static let fromWidget = "fromWidget"
   112→    
   113→    let action: String?
   114→    let api: String?
   115→    
   116→    static func decode(message: String) throws -> DecodedWidgetMessage? {
   117→        guard let data = message.data(using: .utf8) else {
   118→            return nil
   119→        }
   120→        return try decoder.decode(DecodedWidgetMessage.self, from: data)
   121→    }
   122→    
   123→    var hasLoaded: Bool {
   124→        action == Self.contentLoadedAction && api == Self.fromWidget
   125→    }
   126→}
